export const CARD_I18N_BY_CANONICAL_ID: ReadonlyMap<string, FleshAndBloodCardI18n> = (() => {
  const entries = new Map<string, FleshAndBloodCardI18n>();
  for (const { card, i18n } of authoredCards) {
    if (i18n.canonicalId !== card.canonicalId)
      throw new Error(
        `FAB card localization ${i18n.canonicalId} does not match ${card.canonicalId}`,
      );
    if (entries.has(card.canonicalId))
      throw new Error(`Duplicate FAB card localization canonical id: ${card.canonicalId}`);
    entries.set(card.canonicalId, i18n);
  }
  return entries;
})();

export const STRUCTURED_CARDS_BY_CANONICAL_ID: ReadonlyMap<string, FleshAndBloodCard> = (() => {
  const cards = new Map<string, FleshAndBloodCard>();
  for (const { card, i18n } of authoredCards) {
    const localized = localizeFleshAndBloodCard(card, i18n);
    if (cards.has(localized.canonicalId))
      throw new Error(`Duplicate structured FAB card canonical id: ${localized.canonicalId}`);
    cards.set(localized.canonicalId, localized);
  }
  return cards;
})();
